-- Q01 · Estrutura instalada = estrutura calculada a partir dos 6 ficheiros S3 (nomes, contagens, impressões).
-- Os valores esperados saem da montagem (não de uma base): qualquer diferença é FALHA.
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'Q01-01'::text, 'colunas'::text, ((SELECT count(*) || '/' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT c.relname::text || '.' || a.attname::text FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND a.attnum > 0 AND NOT a.attisdropped) a(k)) = '1259/4f040791bef2844fcfc2cfbdb4660387')::boolean, '1259 / 4f040791bef2844fcfc2cfbdb4660387'::text, ((SELECT count(*) || ' / ' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT c.relname::text || '.' || a.attname::text FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND a.attnum > 0 AND NOT a.attisdropped) a(k)))::text
  UNION ALL SELECT 'Q01-02'::text, 'funções (nome/nº argumentos)'::text, ((SELECT count(*) || '/' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT p.proname::text || '/' || p.pronargs::text FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public') a(k)) = '43/699407a25a2904c66d09455f7dad585a')::boolean, '43 / 699407a25a2904c66d09455f7dad585a'::text, ((SELECT count(*) || ' / ' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT p.proname::text || '/' || p.pronargs::text FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public') a(k)))::text
  UNION ALL SELECT 'Q01-03'::text, 'políticas (tabela.nome:comando:tipo:papéis)'::text, ((SELECT count(*) || '/' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT tablename::text || '.' || policyname::text || ':' || cmd::text || ':' || permissive::text || ':' || array_to_string(roles, '+') FROM pg_policies WHERE schemaname = 'public') a(k)) = '226/124f13ac16d4df736958c3e8045fad8f')::boolean, '226 / 124f13ac16d4df736958c3e8045fad8f'::text, ((SELECT count(*) || ' / ' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT tablename::text || '.' || policyname::text || ':' || cmd::text || ':' || permissive::text || ':' || array_to_string(roles, '+') FROM pg_policies WHERE schemaname = 'public') a(k)))::text
  UNION ALL SELECT 'Q01-04'::text, 'gatilhos'::text, ((SELECT count(*) || '/' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT c.relname::text || '.' || t.tgname::text FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND NOT t.tgisinternal) a(k)) = '72/d98bcfe565375440cd4286278bb1e0cb')::boolean, '72 / d98bcfe565375440cd4286278bb1e0cb'::text, ((SELECT count(*) || ' / ' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT c.relname::text || '.' || t.tgname::text FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND NOT t.tgisinternal) a(k)))::text
  UNION ALL SELECT 'Q01-05'::text, 'índices'::text, ((SELECT count(*) || '/' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT ic.relname::text FROM pg_index i JOIN pg_class ic ON ic.oid = i.indexrelid JOIN pg_namespace n ON n.oid = ic.relnamespace WHERE n.nspname = 'public') a(k)) = '297/a60052ea9315dd2906ad6f5ec9144320')::boolean, '297 / a60052ea9315dd2906ad6f5ec9144320'::text, ((SELECT count(*) || ' / ' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT ic.relname::text FROM pg_index i JOIN pg_class ic ON ic.oid = i.indexrelid JOIN pg_namespace n ON n.oid = ic.relnamespace WHERE n.nspname = 'public') a(k)))::text
  UNION ALL SELECT 'Q01-06'::text, 'restrições (sem NOT NULL)'::text, ((SELECT count(*) || '/' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT cl.relname::text || '.' || x.conname::text FROM pg_constraint x JOIN pg_class cl ON cl.oid = x.conrelid JOIN pg_namespace n ON n.oid = cl.relnamespace WHERE n.nspname = 'public' AND x.contype <> 'n') a(k)) = '254/7fcdd658636030c1638b8824152f9866')::boolean, '254 / 7fcdd658636030c1638b8824152f9866'::text, ((SELECT count(*) || ' / ' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT cl.relname::text || '.' || x.conname::text FROM pg_constraint x JOIN pg_class cl ON cl.oid = x.conrelid JOIN pg_namespace n ON n.oid = cl.relnamespace WHERE n.nspname = 'public' AND x.contype <> 'n') a(k)))::text
  UNION ALL SELECT 'Q01-07'::text, 'tipos enum'::text, ((SELECT count(*) || '/' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT t.typname::text FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typtype = 'e') a(k)) = '8/187bdb6645633a2d40e3aae5264f4351')::boolean, '8 / 187bdb6645633a2d40e3aae5264f4351'::text, ((SELECT count(*) || ' / ' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT t.typname::text FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typtype = 'e') a(k)))::text
  UNION ALL SELECT 'Q01-08'::text, 'tabelas com FORCE RLS'::text, ((SELECT count(*) || '/' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT c.relname::text FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relforcerowsecurity) a(k)) = '8/48f8b2f56db2ebd6f3e53e752a5de3d8')::boolean, '8 / 48f8b2f56db2ebd6f3e53e752a5de3d8'::text, ((SELECT count(*) || ' / ' || md5(string_agg(k, ',' ORDER BY k COLLATE "C")) FROM (SELECT c.relname::text FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relforcerowsecurity) a(k)))::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 8 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
